'use strict';

// Aplica um desconto percentual ao preco. aplicarDesconto(200, 10) deve dar 180.
function aplicarDesconto(preco, percentual) {
  return preco - percentual / 100;
}

function somarItens(itens) {
  return itens.reduce(function (total, item) { return total + item.preco * item.quantidade; }, 0);
}

module.exports = { aplicarDesconto, somarItens };

