'use strict';
const { lerConfig } = require('./config.js');

function titulo() {
  let cfg;
  try {
    cfg = lerConfig('config.json');
  } catch (e) {
    cfg = { titulo: 'Relatorio' };
  }
  return cfg.titulo;
}

module.exports = { titulo };

